/** What a country ship of size limit collection can contain. */
export type CountryShipOfSizeLimitItem =
  ContentItem<"country_ship_of_size_limit", CountryShipOfSizeLimitDef> | ContributionItem;

export interface CountryShipOfSizeLimitCollection extends Collection<CountryShipOfSizeLimitItem> {
  /** Defines a country ship of size limit in this mod, registering it in this collection. */
  defineCountryShipOfSizeLimit<const Id extends string>(
    def: CountryShipOfSizeLimitDef<Id>
  ): ContentItem<"country_ship_of_size_limit", CountryShipOfSizeLimitDef<Id>>;

  /**
   * Contributes to the shared additive `default = { ship_of_size_limits = ... }`
   * sink: ids this mod names but does not own, with no author-named file.
   * A ref listed twice is emitted once.
   */
  addShipOfSizeLimits(
    shipOfSizeLimits: readonly (TypedRef<"country_ship_of_size_limit"> | string)[]
  ): void;
}

/**
 * A country ship of size limit collection, optionally bound to a file stem: its definitions
 * land in `common/country_limits/ship_of_size_limits/<prefix>_<file>.txt`, defaulting to the
 * registry's own file name. The definers register into the collection at
 * the definition site, so creating a definition is registering it.
 */
export function createCountryShipOfSizeLimits(file?: string): CountryShipOfSizeLimitCollection {
  const { collection, items } = makeCollection<CountryShipOfSizeLimitItem>(file);
  return {
    ...collection,
    defineCountryShipOfSizeLimit(def) {
      const item = {
        itemKind: "content" as const,
        type: "country_ship_of_size_limit" as const,
        id: def.id,
        def,
      };
      items.push(item);
      return item;
    },
    addShipOfSizeLimits(shipOfSizeLimits) {
      items.push({
        itemKind: "contribution",
        registry: "ship_of_size_limits",
        ids: shipOfSizeLimits.map((entry) => String(refId(entry))),
      });
    },
  };
}
